"""Independent Jacobian/PSD/similarity checks; no optical rendering/fitting."""
import json,copy,hashlib
from pathlib import Path
import numpy as np
import toolbar_scattering_covariance as m
out=Path('/evidence/extended/helper-toolbar-work/agent-toolbar-scattering-covariance');out.mkdir(exist_ok=True)
p=json.loads(Path('/tmp/agent-toolbar-evidence-package/recipe.json').read_text());rng=np.random.default_rng(2401);x=rng.uniform(-2.3,2.3,1500);y=rng.uniform(-1,1,1500);sd=m.baseline.boundary(x,y,p)[0];keep=sd<-.003;x=x[keep];y=y[keep];A,J,flags=m.scattering_factor(x,y,p);regular=~flags['undefined_normal_branch'];errors=[]
for h in [1e-5,5e-6]:
    xp,yp=m.baseline.mapping(x+h,y,p);xm,ym=m.baseline.mapping(x-h,y,p);xu,yu=m.baseline.mapping(x,y+h,p);xd,yd=m.baseline.mapping(x,y-h,p);fd=np.stack([np.stack([(xp-xm)/(2*h),(xu-xd)/(2*h)],-1),np.stack([(yp-ym)/(2*h),(yu-yd)/(2*h)],-1)],-2);err=float(np.max(np.abs((fd-J)[regular])));errors.append({'h':h,'max_absolute_J_error':err,'RMS_J_error':float(np.sqrt(np.mean((fd[regular]-J[regular])**2)))});assert err<1e-4
M=np.einsum('...ik,...jk->...ij',A,A);eigen=np.linalg.eigvalsh(M);assert eigen.min()>-1e-12 and eigen.max()<1 and np.trace(M,axis1=-2,axis2=-1).max()<1
Q=np.array([[-1.,0.],[0.,1.]]);Am,Jm,_=m.scattering_factor(-x,y,p);mirror=float(np.max(np.abs(Am-np.einsum('ij,...jk,lk->...il',Q,A,Q))));rot=copy.deepcopy(p);rot['shape']['half']=list(reversed(p['shape']['half']));rot['parameters']['core_x'],rot['parameters']['core_y']=p['parameters']['core_y'],p['parameters']['core_x'];Q90=np.array([[0.,-1.],[1.,0.]]);Ar,Jr,_=m.scattering_factor(-y,x,rot);rotation=float(np.max(np.abs(Ar-np.einsum('ij,...jk,lk->...il',Q90,A,Q90))));scaled=copy.deepcopy(p);scaled['shape']['half']=[3*v for v in p['shape']['half']];scaled['shape']['radius']*=3;As,Js,_=m.scattering_factor(3*x,3*y,scaled);scale=float(np.max(np.abs(As-A)));assert max(mirror,rotation,scale)<1e-11
cov,_=m.covariance(x,y,p,.02);covscale,_=m.covariance(3*x,3*y,scaled,.02);assert np.max(np.abs(covscale-9*cov))<1e-12;zero,_=m.covariance(x,y,p,0);assert np.array_equal(zero,np.zeros_like(zero));identity=copy.deepcopy(p);identity['parameters'].update(coefficients=[0.]*7,core_x=0.,core_y=0.,tangent=0.);Ai,Ji,_=m.scattering_factor(x,y,identity);assert np.array_equal(Ai,np.zeros_like(Ai));assert np.array_equal(Ji,np.broadcast_to(np.eye(2),Ji.shape))
report={'analytic_J_vs_independent_central_differences':errors,'validated_points':len(x),'undefined_normal_points_in_test':int(flags['undefined_normal_branch'].sum()),'M_eigen_min':float(eigen.min()),'M_eigen_max':float(eigen.max()),'M_trace_max':float(np.trace(M,axis1=-2,axis2=-1).max()),'factor_mirror_error':mirror,'factor_rotation90_error':rotation,'factor_scale3_error':scale,'covariance_scale_law':True,'rho0_added_covariance_exact_zero':True,'identity_transport_factor_exact_zero':True,'uniform_source_invariance':'Analytic: allnormalizedsharedkernelweights sum1. Nativequadrature/render test belongs25if supported.','scope':'Empiricalscattering, not microfacet/physicalroughness. Lens-interior derivative, no AA/source/score change.','model_sha256':hashlib.sha256(Path('/tmp/agent-toolbar-code/toolbar_scattering_covariance.py').read_bytes()).hexdigest(),'new_optical_renders_or_fits':0};(out/'invariants.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2),flush=True)
